/bin/sh -lc "cat >> .codex-role-output/checkpoint.md <<'EOF'

Investigation: VulnInfo only has AlertDict; detector/kevuln.go discards go-kev response details and sets a generic CISA alert. Local go-kev db.Response has CISA []KEVuln and VulnCheck []VulnCheck; DB interface exposes GetKEVByCveID. Root cause: detector has no model mapping for either source. Hypothesis: a shared response-to-KEV mapper used by HTTP and DB paths will preserve source metadata and let summaries/sorting use the dedicated field.
EOF
cat > models/kev_test.go <<'EOF'
package models

import (
    \"testing\"
    \"time\"
)

func TestKEVSummaryAndSort(t *testing.T) {
    r := ScanResult{ScannedCves: VulnInfos{
        \"one\": {KEVs: []KEV{
            {Type: VulnCheckKEVType, VulnerabilityName: \"Z\"},
            {Type: CISAKEVType, VulnerabilityName: \"Z\"},
            {Type: CISAKEVType, VulnerabilityName: \"A\"},
        }},
        \"two\": {},
        \"three\": {KEVs: []KEV{{Type: CISAKEVType}}},
    }}
    if got := r.FormatKEVCveSummary(); got "'!= "2 KEVs" { t.Fatalf("summary = %q", got) }
    r.SortForJSONOutput()
    entries := r.ScannedCves["one"].KEVs
    if entries[0].VulnerabilityName != "A" || entries[1].VulnerabilityName != "Z" || entries[2].Type != VulnCheckKEVType {
        t.Fatalf("unexpected order: %+v", entries)
    }
    _ = time.Time{} // Ensure the model exposes time-based KEV dates below.
    _ = KEV{DateAdded: time.Time{}, DueDate: new(time.Time), CISA: &CISAKEV{Note: "note"}, VulnCheck: &VulnCheckKEV{XDB: []VulnCheckXDB{{XDBID: "id"}}, ReportedExploitation: []VulnCheckReportedExploitation{{URL: "url"}}}}
}
EOF
GOTOOLCHAIN=local GOPROXY=off go test -mod=readonly ./models -run TestKEVSummaryAndSort -count=1'

/bin/sh -lc "cat > detector/kevuln_test.go <<'EOF'
//go:build "'!scanner

package detector

import (
    "testing"
    "time"

    "github.com/future-architect/vuls/models"
    kevulndb "github.com/vulsio/go-kev/db"
    kevulnmodels "github.com/vulsio/go-kev/models"
)

func TestKEVMapping(t *testing.T) {
    added := time.Date(2024, 1, 2, 0, 0, 0, 0, time.UTC)
    response := kevulndb.Response{
        CISA: []kevulnmodels.KEVuln{{VendorProject: "CISA vendor", Product: "c product", VulnerabilityName: "C name", ShortDescription: "C desc", RequiredAction: "C action", KnownRansomwareCampaignUse: "Known", DateAdded: added, Notes: "C note"}},
        VulnCheck: []kevulnmodels.VulnCheck{{VendorProject: "VC vendor", Product: "v product", Name: "V name", Description: "V desc", RequiredAction: "V action", KnownRansomwareCampaignUse: "Unknown", DateAdded: added, DueDate: &added, VulnCheckXDB: []kevulnmodels.VulnCheckXDB{{XDBID: "xdb", XDBURL: "https://xdb", DateAdded: added, ExploitType: "poc", CloneSSHURL: "git@xdb"}}, VulnCheckReportedExploitation: []kevulnmodels.VulnCheckReportedExploitation{{URL: "https://report", DateAdded: added}}}},
    }
    got := toKEVs(response)
    if len(got) != 2 { t.Fatalf("got %d KEVs", len(got)) }
    if got[0].Type != models.CISAKEVType || got[0].VendorProject != "CISA vendor" || got[0].DueDate != nil || got[0].CISA.Note != "C note" { t.Errorf("CISA mapping: %+v", got[0]) }
    if got[1].Type != models.VulnCheckKEVType || got[1].VulnerabilityName != "V name" || got[1].DueDate == nil || len(got[1].VulnCheck.XDB) != 1 || got[1].VulnCheck.XDB[0].CloneSSHURL != "git@xdb" || len(got[1].VulnCheck.ReportedExploitation) != 1 { t.Errorf("VulnCheck mapping: %+v", got[1]) }
}
EOF
GOTOOLCHAIN=local GOPROXY=off go test -mod=readonly ./detector -run TestKEVMapping -count=1'
